/**
 * seedData — 500+ realistic interior design materials across 13 categories.
 * Used by the idempotent seed function (upsert on materialCode).
 */

export interface SeedMaterial {
  materialCode: string;
  name: string;
  slug: string;
  category: string;
  subcategory: string;
  brand: string;
  materialType: string;
  color: string;
  finish: string;
  texture: string;
  pattern: string;
  description: string;
  priceTier: string;
  searchKeywords: string[];
}

function mat(
  code: string, name: string, cat: string, sub: string, brand: string,
  type: string, color: string, finish: string, texture: string, pattern: string,
  desc: string, tier: string, keywords: string[],
): SeedMaterial {
  const slug = `${code.toLowerCase().replace(/-/g, "-")}`;
  return { materialCode: code, name, slug, category: cat, subcategory: sub, brand, materialType: type, color, finish, texture, pattern, description: desc, priceTier: tier, searchKeywords: keywords };
}

